#include <bits/stdc++.h>
using namespace std;

const int MAXN = 300;
const int ROOM = -1, REAC = -2, BAD_REAC = -3, CAPS = ROOM;

struct Edge {
    int from, to, rev, flow, cap;
    Edge() {}
    Edge(int f, int t, int r, int fl, int c) : from(f), to(t), rev(r), flow(fl), cap(c) {}
    int residual() { return cap - flow; }
};

class FlowNetwork {
public:
    int n;
    vector<Edge*> *graph;
    Edge **parent;
    bool *visited;

    FlowNetwork(int size) {
        n = size;
        graph = new vector<Edge*>[n];
        parent = new Edge*[n];
        visited = new bool[n];
    }

    void reset() {
        for (int i=0; i<n; i++) {
            for (auto e : graph[i]) delete e;
            graph[i].clear();
        }
    }

    void cleanup() {
        reset();
        delete[] parent;
        delete[] visited;
        delete this;
    }

    void connect(int s, int t, int capacity) {
        Edge *a = new Edge(s, t, (int)graph[t].size(), 0, capacity);
        Edge *b = new Edge(t, s, (int)graph[s].size(), 0, 0);
        graph[s].push_back(a);
        graph[t].push_back(b);
    }

    void connect_bi(int s, int t, int capacity) {
        Edge *a = new Edge(s, t, (int)graph[t].size(), 0, capacity);
        Edge *b = new Edge(t, s, (int)graph[s].size(), 0, capacity);
        graph[s].push_back(a);
        graph[t].push_back(b);
    }

    bool find_path(int source, int sink) {
        for (int i=0; i<n; i++) {
            parent[i] = nullptr;
            visited[i] = false;
        }
        queue<int> q;
        q.push(source);
        visited[source] = true;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            if (u == sink) return true;
            for (auto e : graph[u]) {
                if (!visited[e->to] && e->residual() > 0) {
                    parent[e->to] = e;
                    visited[e->to] = true;
                    q.push(e->to);
                }
            }
        }
        return false;
    }

    int augment(int s, int t) {
        int flow = INT_MAX;
        int v = t;
        while (v != s) {
            flow = min(flow, parent[v]->residual());
            v = parent[v]->from;
        }
        v = t;
        while (v != s) {
            parent[v]->flow += flow;
            graph[parent[v]->to][parent[v]->rev]->flow -= flow;
            v = parent[v]->from;
        }
        return flow;
    }

    long long compute(int s, int t) {
        int total = 0;
        while (find_path(s, t)) {
            total += augment(s, t);
        }
        return total;
    }
};

int station[MAXN][MAXN], checkpoint[MAXN][MAXN], poison[61][MAXN][MAXN];

struct Coord {
    int x, y, quantity;
    Coord(int a, int b, int c) : x(a), y(b), quantity(c) {}
    bool valid(int N) { return (x >= 0 && x < N && y >= 0 && y < N && station[x][y] == ROOM); }
};

bool is_valid(int x, int y, int N) {
    return Coord(x, y, 0).valid(N);
}

inline bool operator==(const Coord &a, const Coord &b) {
    return (a.x == b.x && a.y == b.y);
}

vector<Coord> evacuees, capsules;
int deltaX[] = {-1, 0, 1, 0};
int deltaY[] = {0, -1, 0, 1};

int translate_char(char ch) {
    if (ch >= '0' && ch <= '9') return ROOM;
    if (ch == 'Y') return REAC;
    if (ch == 'Z') return BAD_REAC;
    return -1;
}

int get_qty(char ch) {
    return ch - '0';
}

int shortest_path(Coord start, Coord end, int N) {
    bitset<MAXN> visited[MAXN];
    queue<pair<int, Coord>> q;
    q.push({0, start});
    visited[start.x][start.y] = 1;
    while (!q.empty()) {
        int time = q.front().first;
        Coord curr = q.front().second;
        q.pop();
        if (curr == end) return time;
        if (poison[time][curr.x][curr.y]) continue;
        for (int i=0; i<4; i++) {
            Coord next(curr.x + deltaX[i], curr.y + deltaY[i], 0);
            if (next.valid(N) && !visited[next.x][next.y]) {
                if (!poison[time][next.x][next.y]) {
                    q.push({time + 1, next});
                    visited[next.x][next.y] = 1;
                }
            }
        }
    }
    return 999;
}

void poison_spread(int x, int y, int T, int N) {
    poison[0][x][y] = 1;
    for (int t=1; t<=T; t++) {
        for (int i=0; i<N; i++) {
            for (int j=0; j<N; j++) {
                if (poison[t-1][i][j]) {
                    poison[t][i][j] = 1;
                    for (int move=0; move<4; move++) {
                        int nx = i + deltaX[move], ny = j + deltaY[move];
                        if (is_valid(nx, ny, N))
                            poison[t][nx][ny] = 1;
                    }
                }
            }
        }
    }
}

int main() {
    int N, T;
    scanf("%d %d", &N, &T);
    char ch;
    Coord bad(0,0,0);
    for (int i=0; i<N; i++) {
        for (int j=0; j<N; j++) {
            scanf(" %c", &ch);
            int val = translate_char(ch);
            station[i][j] = val;
            if (val == ROOM && get_qty(ch))
                evacuees.push_back(Coord(i,j,get_qty(ch)));
            if (val == BAD_REAC)
                bad = Coord(i,j,0);
        }
    }
    for (int i=0; i<N; i++) {
        for (int j=0; j<N; j++) {
            scanf(" %c", &ch);
            int val = translate_char(ch);
            if (val == CAPS && get_qty(ch)) {
                capsules.push_back(Coord(i,j,get_qty(ch)));
                checkpoint[i][j] = get_qty(ch);
            }
        }
    }
    FlowNetwork *fn = new FlowNetwork(MAXN);
    int sink = MAXN - 1;
    for (size_t i=0; i<evacuees.size(); i++) {
        fn->connect(0, i*2+1, evacuees[i].quantity);
    }
    for (size_t i=0; i<capsules.size(); i++) {
        fn->connect_bi(i*2+2, sink, capsules[i].quantity);
    }
    poison_spread(bad.x, bad.y, T, N);
    for (size_t i=0; i<evacuees.size(); i++) {
        for (size_t j=0; j<capsules.size(); j++) {
            int time_needed = shortest_path(evacuees[i], capsules[j], N);
            if (time_needed <= T) {
                fn->connect_bi(i*2+1, j*2+2, 999);
            }
        }
    }
    printf("%lld\n", fn->compute(0, sink));
    delete fn;
    return 0;
}
